            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xB0DEEC3E391D8EE6ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0xAC7BDB79D35A6C5AULL;
