            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x1656D452B3041B67ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0xEC5B63360BFA3AB0ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x45BC4116DBCA4EE3ULL), 47U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0xEE2F816D253F8BB0ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x55C719063D2CF637ULL;
