            //
            aOrbiterC = ((aWandererG + RotL64(aIngress, 58U)) + RotL64(aCarry, 27U)) + 0xA64A0A1D6985658BULL;
            aOrbiterD = (((aWandererD + RotL64(aCross, 27U)) + RotL64(aCarry, 51U)) + 0xAAEBEF65AB2C915EULL) + aOASaltG[((aIndex + 32U)) & S_SALT1];
            aOrbiterK = ((aWandererH + RotL64(aPrevious, 51U)) + 0x04D12AAE415710B3ULL) + aOASaltA[(((511U - aIndex) + 293U)) & S_SALT1];
            aOrbiterF = (aWandererK + RotL64(aScatter, 11U)) + 0xB9FC55C056E45971ULL;
            aOrbiterE = (aWandererF + RotL64(aIngress, 39U)) + 0xD0C650122416A404ULL;
            aOrbiterH = ((aWandererE + RotL64(aScatter, 53U)) + 0x36C6AF942C0D1E14ULL) + aOASaltF[(((511U - aIndex) + 406U)) & S_SALT1];
            aOrbiterI = ((aWandererC + RotL64(aCross, 21U)) + 0xA65AB2DF17583095ULL) + aOASaltH[((aIndex + 245U)) & S_SALT1];
