            aOrbiterD = (aWandererH + RotL64(aCross, 47U)) + 0xB5982B6ECDAD0525ULL;
            aOrbiterH = (((aWandererF + RotL64(aPrevious, 53U)) + RotL64(aCarry, 5U)) + 0x147C55BDD691B208ULL) + aOASaltE[((aIndex + 474U)) & S_SALT1];
            aOrbiterE = ((aWandererA + RotL64(aIngress, 19U)) + 0xAE0EEB580ACBA14DULL) + aOASaltH[(((511U - aIndex) + 442U)) & S_SALT1];
            aOrbiterA = (((aWandererG + RotL64(aScatter, 35U)) + RotL64(aCarry, 35U)) + 0xDB9BB2EF18C3C515ULL) + aOASaltF[(((511U - aIndex) + 370U)) & S_SALT1];
