            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x848E591D39AC19FAULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x07497B53DD702063ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xA4AC74FD6B870F8BULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xAB6713D072134263ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0xF8930FDB3AE8087BULL;
            aOrbiterG = RotL64((aOrbiterG * 0xD1F068A907477045ULL), 51U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterG) + 0x2B4695E242B2131DULL) + aOUSaltC[((aIndex + 321U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x7453588DA187EE33ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x78AC918A7D76F691ULL), 53U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x84C5532F237A7590ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x9D937B520CDD01D7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x1D081D09185D5C25ULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0xDAF8DE2FC0441959ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0xE8995E91711C1710ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x95CDE4D5D753F833ULL), 39U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0xB1BA102C4949C782ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0x8C3462AE5DD0E8D0ULL;
