            //
            aOrbiterH = ((aOrbiterH + aOrbiterJ) + 0x25158DEA1A0701B2ULL) + aOUSaltA[((aIndex + 167U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0x323FB27A69363739ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xBCAE0D89F2363109ULL), 23U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xDA55748D5C6C76DBULL;
