            //
            aOrbiterK = (((aWandererA + RotL64(aCross, 57U)) + RotL64(aCarry, 39U)) + 0x083EE1B205E34AF6ULL) + aOASaltA[((aIndex + 225U)) & S_SALT1];
            aOrbiterB = (((aWandererI + RotL64(aPrevious, 21U)) + RotL64(aCarry, 53U)) + 0x62EB69BF0B072212ULL) + aOASaltF[(((511U - aIndex) + 254U)) & S_SALT1];
            aOrbiterH = (aWandererH + RotL64(aScatter, 43U)) + 0x233AC18EBB34DC94ULL;
            aOrbiterC = (((aWandererC + RotL64(aIngress, 29U)) + RotL64(aCarry, 21U)) + 0xA9C38F4C40C1765AULL) + aOASaltE[(((511U - aIndex) + 282U)) & S_SALT1];
            aOrbiterG = (aWandererF + RotL64(aPrevious, 51U)) + 0x4862B06987AE8B32ULL;
            aOrbiterE = (aWandererE + RotL64(aIngress, 12U)) + 0x49AD1911866C17D2ULL;
            aOrbiterF = (aWandererD + RotL64(aScatter, 5U)) + 0xA5B642389795316AULL;
