            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0xAA798175653246E5ULL) + aOUSaltC[((aIndex + 347U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterF) ^ 0x93D380E60A104432ULL) ^ aOUSaltB[((aIndex + 409U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x27B4A54C8AF23689ULL), 57U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterH, 41U);
