            aIngress = aIngress + RotL64(aOrbiterE, 35U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererF = aWandererF ^ (((RotL64(aScatter, 47U) + aOrbiterB) + RotL64(aOrbiterE, 3U)) + aWUSaltB[(((511U - aIndex) + 114U)) & S_SALT1]);
