            aCross ^= (RotL64(aCrystalLaneD[((S_BLOCK1 - aIndex + 14580U)) & S_BLOCK1], 21U) ^ RotL64(aEarthLaneA[((aIndex + 15374U)) & S_BLOCK1], 47U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCarry, 51U) + RotL64(aPrevious, 22U)) ^ (RotL64(aIngress, 35U) ^ RotL64(aCross, 5U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterJ = ((aWandererI + RotL64(aScatter, 3U)) + 0x5AC44B3DEB88414DULL) + aOASaltF[(((511U - aIndex) + 165U)) & S_SALT1];
            aOrbiterI = (aWandererE + RotL64(aIngress, 11U)) + 0x43414CA4160F561FULL;
            aOrbiterK = (((aWandererA + RotL64(aPrevious, 41U)) + RotL64(aCarry, 41U)) + 0x5E54EBF3F30AC5B0ULL) + aOASaltD[(((511U - aIndex) + 453U)) & S_SALT1];
            aOrbiterA = ((aWandererF + RotL64(aCross, 20U)) + RotL64(aCarry, 3U)) + 0x0B43862EC694D551ULL;
            aOrbiterH = ((aWandererB + RotL64(aIngress, 35U)) + 0xC82249456A3ED0C3ULL) + aOASaltH[((aIndex + 133U)) & S_SALT1];
            aOrbiterB = ((aWandererK + RotL64(aCross, 27U)) + 0x2136B9C37D737B49ULL) + aOASaltB[(((511U - aIndex) + 457U)) & S_SALT1];
            aOrbiterE = (((aWandererD + RotL64(aScatter, 57U)) + RotL64(aCarry, 19U)) + 0x5439BE57F5130C7BULL) + aOASaltA[((aIndex + 347U)) & S_SALT1];
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterI) + 0xD0EE287D37A9D64AULL) + aOUSaltH[(((511U - aIndex) + 487U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0x85CC36F781742594ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x133C14749EFCD747ULL), 53U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x5A7F1A7E84861F0FULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x6AC7894CE7479898ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x21F2AC264C05A139ULL), 5U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterA) + 0x18D786753E4B6BC4ULL) + aOUSaltA[(((511U - aIndex) + 77U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x6F7F568F18E55C53ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x577B96EDB5DD843DULL), 47U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0xC82AE5B0F4317374ULL) + aOUSaltD[((aIndex + 454U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0xD5E4D8B0733B4E26ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x929CC2F186A0C591ULL), 35U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0x8D4373F744C765BAULL) + aOUSaltC[((aIndex + 228U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0x589512EA8142D650ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x62D532EDBEEE549BULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0xC29111C61B51DE12ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterI) ^ 0x38A883BB2D44A654ULL) ^ aOUSaltG[(((511U - aIndex) + 392U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xD26D8E47ADF81FAFULL), 41U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xFD1A07DE0AA65D38ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterB) ^ 0x57F579E635D41CD2ULL) ^ aOUSaltE[((aIndex + 443U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x206C30F8F54AE2BFULL), 23U);
