            aIngress = aIngress + RotL64(aOrbiterI, 37U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererI = aWandererI ^ (((RotL64(aIngress, 3U) + aOrbiterA) + RotL64(aOrbiterH, 11U)) + aWUSaltC[(((511U - aIndex) + 354U)) & S_SALT1]);
            aWandererE = aWandererE + ((((RotL64(aScatter, 29U) + aOrbiterI) + RotL64(aOrbiterE, 3U)) + RotL64(aCarry, 51U)) + aWUSaltG[((aIndex + 500U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aCross, 19U) + RotL64(aOrbiterK, 27U)) + aOrbiterE);
            aWandererB = aWandererB + (((RotL64(aPrevious, 11U) + aOrbiterA) + RotL64(aOrbiterJ, 50U)) + RotL64(aCarry, 35U));
            aWandererA = aWandererA ^ ((RotL64(aCross, 43U) + aOrbiterI) + RotL64(aOrbiterA, 35U));
            aWandererD = aWandererD + (((RotL64(aScatter, 57U) + aOrbiterE) + RotL64(aOrbiterB, 57U)) + aWUSaltA[(((511U - aIndex) + 109U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aPrevious, 36U) + RotL64(aOrbiterA, 43U)) + aOrbiterK) + aWUSaltB[((aIndex + 320U)) & S_SALT1]);
