            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 18U) + RotL64(aCarry, 5U)) ^ (RotL64(aPrevious, 53U) + RotL64(aCross, 35U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterJ = (((aWandererB + RotL64(aScatter, 43U)) + RotL64(aCarry, 39U)) + 0x56AE26CAB4390CC2ULL) + aOASaltD[((aIndex + 496U)) & S_SALT1];
            aOrbiterH = ((aWandererA + RotL64(aCross, 3U)) + RotL64(aCarry, 23U)) + 0x74B1FC73C47DBF19ULL;
            aOrbiterA = ((aWandererG + RotL64(aIngress, 21U)) + 0x4852B820DC9E9BB4ULL) + aOASaltH[(((511U - aIndex) + 55U)) & S_SALT1];
            aOrbiterF = (((aWandererE + RotL64(aPrevious, 12U)) + RotL64(aCarry, 3U)) + 0xC73CA4ED0B5F88DEULL) + aOASaltC[(((511U - aIndex) + 47U)) & S_SALT1];
            aOrbiterD = (aWandererH + RotL64(aCross, 29U)) + 0x46308106AAF56904ULL;
            aOrbiterI = ((aWandererK + RotL64(aScatter, 57U)) + 0x85951B581EBAB82EULL) + aOASaltA[(((511U - aIndex) + 316U)) & S_SALT1];
            aOrbiterK = (aWandererI + RotL64(aIngress, 37U)) + 0xAF590763DA210F0DULL;
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterH) + 0xEE2ED2B48C376694ULL) + aOUSaltF[(((511U - aIndex) + 147U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x4BADAC2E27AEDEE8ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xC7B5B22D568A6DB9ULL), 57U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x612D9AD992EDAD4AULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x7017C361BE42F727ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x0B8DF4852A6C9971ULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x2773DAD771A88385ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterD) ^ 0xADB1095CB9819367ULL) ^ aOUSaltB[((aIndex + 386U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x3CD586F3C1580CBBULL), 35U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xA28CF0DC3CDB6C08ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterK) ^ 0x8466EAE6F7B58702ULL) ^ aOUSaltD[(((511U - aIndex) + 503U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xFB492E2C9FDBD43BULL), 47U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x2688A4A3BC1857ACULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0x5F7C88A9813649C2ULL) ^ aOUSaltA[(((511U - aIndex) + 173U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x197C068184DC3E3BULL), 11U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterJ) + 0x626971F5D046FCD0ULL) + aOUSaltE[((aIndex + 329U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0xA71CDFC91906BD65ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x974BE0D4F2408C8DULL), 41U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0xFEBE68139244782CULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x13C303B9F6CDB7BCULL;
            aOrbiterD = RotL64((aOrbiterD * 0x705DAB09927B954FULL), 29U);
            //
            aIngress = RotL64(aOrbiterK, 35U) ^ aOrbiterI;
            aIngress = aIngress + (RotL64(aOrbiterF, 48U) ^ aOrbiterD);
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterH, 13U));
            aIngress = aIngress + RotL64(aOrbiterA, 19U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ (((RotL64(aIngress, 57U) + RotL64(aOrbiterD, 42U)) + aOrbiterF) + aWUSaltF[((aIndex + 219U)) & S_SALT1]);
            aWandererH = aWandererH + ((((RotL64(aPrevious, 13U) + aOrbiterK) + RotL64(aOrbiterI, 57U)) + RotL64(aCarry, 51U)) + aWUSaltA[((aIndex + 187U)) & S_SALT1]);
