            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 10U) ^ RotL64(aIngress, 39U)) + (RotL64(aCarry, 23U) ^ RotL64(aPrevious, 57U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterE = ((aWandererB + RotL64(aIngress, 29U)) + 0x5F3C0CE3D5B43269ULL) + aOASaltE[(((511U - aIndex) + 349U)) & S_SALT1];
            aOrbiterB = (aWandererI + RotL64(aPrevious, 44U)) + 0x40C101D9249E2C4AULL;
            aOrbiterC = ((aWandererJ + RotL64(aCross, 19U)) + 0x74380C979F51E566ULL) + aOASaltH[((aIndex + 294U)) & S_SALT1];
            aOrbiterH = (((aWandererC + RotL64(aScatter, 5U)) + RotL64(aCarry, 51U)) + 0xD1424CA3D286EF8EULL) + aOASaltD[(((511U - aIndex) + 435U)) & S_SALT1];
            aOrbiterK = ((aWandererF + RotL64(aCross, 53U)) + RotL64(aCarry, 37U)) + 0xF73562F33DD18915ULL;
            aOrbiterG = ((aWandererA + RotL64(aPrevious, 11U)) + 0x3BEA513E60B2D3E3ULL) + aOASaltC[((aIndex + 259U)) & S_SALT1];
            aOrbiterI = ((aWandererE + RotL64(aIngress, 37U)) + RotL64(aCarry, 13U)) + 0xC52E5ECC8B08C8D0ULL;
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0xCEF8C3114CED8A9CULL) + aOUSaltB[((aIndex + 480U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0x99964D54292396D2ULL) ^ aOUSaltE[(((511U - aIndex) + 425U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xEFDDEA6A34508B77ULL), 41U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0xB3039604DC177D07ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterH) ^ 0xDEBAACBBC164383CULL) ^ aOUSaltD[(((511U - aIndex) + 263U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x4DC46BB5CDD7BA6FULL), 13U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x0F4EF24D9CD6A6D6ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x24B65EA372B04C2EULL;
            aOrbiterI = RotL64((aOrbiterI * 0xFDF27BBE65A6BD85ULL), 3U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterC) + 0x3BD3226C51D5AB23ULL) + aOUSaltA[((aIndex + 190U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x61F9A683CE4BDA5DULL;
            aOrbiterK = RotL64((aOrbiterK * 0x44F1A77DFD22A67DULL), 35U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x7DF110C6650BC07CULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0xE0A195654444370DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x3F79D1E629EDD1E9ULL), 29U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x14EE657B5F1A2E55ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0xA23AD1E3E6E95537ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x63050CE7B66E897DULL), 19U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterK) + 0x1A051376E470C257ULL) + aOUSaltH[(((511U - aIndex) + 497U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x5DA9CB47C840F758ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x51873D0D8D95A7DFULL), 53U);
            //
            aIngress = aOrbiterI ^ RotL64(aOrbiterK, 35U);
