            aWandererF = aWandererF ^ ((RotL64(aIngress, 27U) + aOrbiterI) + RotL64(aOrbiterH, 51U));
            aWandererI = aWandererI + ((((RotL64(aScatter, 11U) + RotL64(aOrbiterG, 37U)) + aOrbiterH) + RotL64(aCarry, 47U)) + aWUSaltG[((aIndex + 102U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ (((RotL64(aPrevious, 3U) + aOrbiterE) + RotL64(aOrbiterH, 19U)) + aWUSaltA[(((511U - aIndex) + 116U)) & S_SALT1]);
            aWandererC = aWandererC + (((RotL64(aCross, 57U) + RotL64(aOrbiterC, 57U)) + aOrbiterB) + RotL64(aCarry, 19U));
            aWandererE = aWandererE ^ ((RotL64(aIngress, 43U) + aOrbiterE) + RotL64(aOrbiterC, 27U));
            aWandererA = aWandererA + (((RotL64(aScatter, 18U) + aOrbiterC) + RotL64(aOrbiterK, 3U)) + aWUSaltH[((aIndex + 57U)) & S_SALT1]);
