            //
            aOrbiterK = ((aWandererA + RotL64(aCross, 13U)) + 0xDF9B26A6835B2442ULL) + aOASaltD[((aIndex + 99U)) & S_SALT1];
            aOrbiterI = ((aWandererK + RotL64(aPrevious, 27U)) + 0x7264153D41C70BCFULL) + aOASaltH[(((511U - aIndex) + 382U)) & S_SALT1];
            aOrbiterJ = (aWandererH + RotL64(aIngress, 57U)) + 0x5A54E6F609AD3B8EULL;
            aOrbiterH = ((aWandererG + RotL64(aScatter, 3U)) + RotL64(aCarry, 5U)) + 0x5E1667140EEA5AC9ULL;
            aOrbiterC = (((aWandererJ + RotL64(aCross, 50U)) + RotL64(aCarry, 47U)) + 0xCF61C0A991EF373CULL) + aOASaltC[((aIndex + 284U)) & S_SALT1];
