    const std::uint64_t &aKeyRotateBDomainWordScatter = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mScatter;
    const std::uint64_t &aKeyRotateBDomainWordCross = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mCross;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

