            aIngress = (RotL64(aWindLaneD[((aIndex + 3823U)) & S_BLOCK1], 60U) ^ RotL64(aWindLaneB[((aIndex + 5279U)) & S_BLOCK1], 29U));
            aIngress ^= (RotL64(aMagmaLaneD[((aIndex + 4199U)) & S_BLOCK1], 11U) ^ RotL64(aAetherLaneC[((S_BLOCK1 - aIndex + 422U)) & S_BLOCK1], 41U));
